INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('2026 Mezunlar Buluşması Tarihi Belirlendi', 'Geleneksel yıllık mezunlar buluşmamız bu yıl 25 Ekim tarihinde ana kampüste gerçekleştirilecektir. Tüm mezunlarımız davetlidir.', 'Rektörlük Mezun Ofisi', 'Etkinlik', 'Önemli', '2026-10-10') ON CONFLICT DO NOTHING;
INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('Kariyer ve Mentorluk Ağı Başvuruları Başladı', 'Genç mezunlarımıza kariyer yolculuklarında rehberlik etmek isteyen deneyimli mezunlarımız için mentorluk kayıtları açılmıştır.', 'Kariyer Merkezi', 'Kariyer', 'Normal', '2026-10-12') ON CONFLICT DO NOTHING;
INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('Yazılım ve Yapay Zeka Zirvesi', 'Farklı ülkelerdeki mezunlarımızın online sunum yapacağı yıllık teknoloji zirvesi kayıtları başladı.', 'Mühendislik Fakültesi', 'Akademik', 'Önemli', '2026-10-14') ON CONFLICT DO NOTHING;
INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('Yurtdışı Yüksek Lisans Burs Fırsatları', 'Avrupa ve Amerika daki partner üniversitelerimizde geçerli burs imkanları hakkında bilgilendirme toplantısı yapılacaktır.', 'Uluslararası İlişkiler Ofisi', 'Akademik', 'Önemli', '2026-06-08') ON CONFLICT DO NOTHING;
INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('2026 Mezunlar Buluşması Tarihi Belirlendi', 'Geleneksel yıllık mezunlar buluşmamız bu yıl 25 Ekim tarihinde ana kampüste gerçekleştirilecektir. Tüm mezunlarımız davetlidir.', 'Rektörlük Mezun Ofisi', 'Etkinlik', 'Önemli', '2026-03-03') ON CONFLICT DO NOTHING;
INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('Kariyer ve Mentorluk Ağı Başvuruları Başladı', 'Genç mezunlarımıza kariyer yolculuklarında rehberlik etmek isteyen deneyimli mezunlarımız için mentorluk kayıtları açılmıştır.', 'Kariyer Merkezi', 'Kariyer', 'Normal', '2026-01-10') ON CONFLICT DO NOTHING;
INSERT INTO announcements (title, content, author, category, priority, date) VALUES ('Start-up ve Girişimcilik Fonu Açıldı', 'Kendi şirketini kurmak isteyen mezunlarımız için kuluçka merkezi hibe ve mentorluk destek programı duyurulmuştur.', 'Teknoloji Transfer Ofisi', 'Kariyer', 'Önemli', '2026-09-16') ON CONFLICT DO NOTHING;
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Trendyol', 'Senior Backend Developer (Node.js & Go)', 'Yazılım Geliştirme', 'Milyonlarca aktif kullanıcıya hizmet veren yüksek trafikli mikroservis mimarimizde görev alacak, Node.js ve Go ekosisteminde tecrübeli Senior Backend Developer arıyoruz.', '• En az 4 yıl Node.js veya Go ile backend geliştirme tecrübesi\n• PostgreSQL, Redis ve Kafka/RabbitMQ mesaj kuyrukları deneyimi\n• Docker & Kubernetes ortamlarında mikroservis geliştirme ve dağıtım tecrübesi\n• Yüksek erişilebilirlik (HA) ve temiz kod (Clean Architecture/DDD) prensiplerine hakimiyet', '• Özel sağlık sigortası (kapsamlı aile paketi)\n• Hibrit çalışma modeli ve aylık evden çalışma ödeneği\n• Yıllık teknoloji ve eğitim bütçesi (1500 USD)\n• Yemek kartı ve servis imkanı', 'full-time', 'hybrid', 'senior', 'İstanbul, Türkiye', 95000, 145000, 'TRY', true, 'https://kariyer.trendyol.com/jobs', 'careers@trendyol.com', '2026-11-20', 'open', true, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Getir', 'Lead Cloud & DevOps Engineer', 'DevOps & Bulut', 'Global pazarlarda ölçeklenen bulut altyapımızın güvenliği, otomasyonu ve yüksek sürekliliğinden sorumlu olacak Lead DevOps Engineer arıyoruz.', '• En az 6 yıl DevOps / SRE tecrübesi\n• İleri düzey AWS/GCP bulut mimarisi ve Terraform (IaC) uzmanlığı\n• Kubernetes (EKS/GKE), Helm ve GitOps (ArgoCD) deneyimi\n• CI/CD pipeline tasarımı ve Prometheus/Grafana ile gözlemlenebilirlik (Observability)', '• Tamamen uzaktan çalışma (Remote-first)\n• Yıllık performans primi ve hisse opsiyonu (ESOP)\n• Özel sağlık sigortası ve spor salonu üyeliği\n• İngilizce dil eğitim desteği', 'full-time', 'remote', 'lead', 'Remote / Türkiye Geneli', 120000, 180000, 'TRY', true, 'https://kariyer.getir.com/jobs', 'careers@getir.com', '2026-11-27', 'open', true, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Google', 'AI & Data Science Specialist', 'Veri ve Yapay Zeka', 'Büyük ölçekli veri analitiği, doğal dil işleme (NLP) ve üretken yapay zeka (LLM) çözümleri geliştirecek araştırmacı ve vizyoner Yapay Zeka Uzmanı arıyoruz.', '• Bilgisayar veya İlgili Mühendislik lisans/yüksek lisans derecesi\n• Python, PyTorch/TensorFlow, scikit-learn ve Pandas uzmanlığı\n• LLM optimizasyonu, RAG mimarileri ve vektör veritabanları (Pinecone/Milvus) tecrübesi\n• Büyük veri araçları (Spark, BigQuery) tecrübesi tercih sebebidir', '• Kapsamlı global yan haklar ve özel sağlık güvencesi\n• Uluslararası konferans katılım sponsorlukları\n• Hibrit çalışma modeli ve ergonomik ev ofis ekipman desteği\n• Ücretsiz yemek ve servis', 'full-time', 'hybrid', 'senior', 'İstanbul, Türkiye', 130000, 200000, 'TRY', true, 'https://kariyer.google.com/jobs', 'careers@google.com', '2026-12-04', 'open', true, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Aselsan', 'Savunma Sistemleri Yazılım Mühendisi', 'Gömülü Sistemler', 'Milli savunma sanayi projelerimizde görev alacak, gerçek zamanlı gömülü sistemler ve görev kritik yazılım mimarilerinde çalışacak mühendisler arıyoruz.', '• C/C++ dillerinde ileri seviye yetkinlik\n• RTOS (FreeRTOS, VxWorks) ve gömülü Linux tecrübesi\n• DO-178C veya savunma standartlarına aşinalık\n• Mikrodenetleyici (ARM Cortex-M/R) ve haberleşme protokolleri (CAN, SPI, UART, Ethernet)', '• Kapsamlı servis ve kurumsal lojman/yemekhane imkanları\n• Lisansüstü eğitim için tam gün akademik izin desteği\n• Yılda iki maaş ikramiye ve özel sağlık sigortası\n• Bireysel emeklilik katkısı (BES)', 'full-time', 'on-site', 'mid', 'İstanbul, Türkiye', 80000, 125000, 'TRY', true, 'https://kariyer.aselsan.com/jobs', 'careers@aselsan.com', '2026-12-11', 'open', false, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Hepsiburada', 'Frontend Architect (React & Next.js)', 'Yazılım Geliştirme', 'E-ticaret platformumuzun modern web arayüzlerinin mimarisini yönetecek, performans optimizasyonu ve Core Web Vitals konularına hakim Frontend mimarı arıyoruz.', '• En az 5 yıl modern JavaScript / TypeScript ve React ekosistemi deneyimi\n• Next.js, SSR, SSG ve micro-frontend mimarileri uzmanlığı\n• Web Vitals, SEO ve sayfa açılış hızı optimizasyonu tecrübesi\n• State yönetimi (Redux Toolkit, Zustand) ve test kütüphaneleri (Jest, Playwright)', '• Esnek ve hibrit çalışma saatleri\n• Şirket içi indirim çeki ve alışveriş kredisi\n• Özel sağlık sigortası ve diş paketi\n• Sürekli eğitim platformu (Udemy, Coursera) üyeliği', 'full-time', 'hybrid', 'senior', 'İstanbul, Türkiye', 90000, 140000, 'TRY', true, 'https://kariyer.hepsiburada.com/jobs', 'careers@hepsiburada.com', '2026-12-18', 'open', false, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Garanti BBVA', 'Siber Güvenlik Operasyonları (SOC) Analisti', 'Siber Güvenlik', 'Bankacılık altyapımızın siber tehditlere karşı 7/24 izlenmesi, olay müdahalesi (Incident Response) ve tehdit avcılığı (Threat Hunting) süreçlerinde görev alacak SOC Analisti arıyoruz.', '• SIEM çözümleri (Splunk, QRadar) ve EDR sistemleri deneyimi\n• Ağ güvenliği, firewall, IDS/IPS sistemleri ve paket analizi (Wireshark)\n• CEH, CompTIA Security+ veya benzeri güvenlik sertifikaları\n• Olay inceleme ve kök neden analizi tecrübesi', '• Finans sektörü prim ve çift ikramiye sistemi\n• Kapsamlı özel sağlık sigortası ve check-up paketi\n• Kreş desteği ve çalışan esenlik programları\n• Bankacılık ürünlerinde özel çalışan faiz indirimleri', 'full-time', 'hybrid', 'mid', 'İstanbul, Türkiye', 75000, 110000, 'TRY', true, 'https://kariyer.garantibbva.com/jobs', 'careers@garantibbva.com', '2026-12-25', 'open', false, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Baykar', 'İHA Otonom Uçuş Kontrol Yazılım Mühendisi', 'Gömülü Sistemler', 'Dünya lideri insansız hava araçlarımızın uçuş kontrol algoritmaları, navigasyon ve otonom görev sistemlerinde görev alacak ekip arkadaşları arıyoruz.', '• C/C++ ve Python dillerinde güçlü yazılım bilgisi\n• Kontrol teorisi, Kalman filtreleri ve uçuş dinamiği temellerine hakimiyet\n• ROS (Robot Operating System) ve simülasyon ortamları (Gazebo, MATLAB/Simulink)\n• Takım çalışmasına yatkınlık ve yoğun AR-GE ortamına uyum', '• Milli teknoloji projelerinde doğrudan yer alma imkanı\n• Kampüs içi spor, sosyal tesisler ve tam kapsamlı yemekhane\n• Yüksek lisans ve doktora burs teşvikleri\n• Özel sağlık sigortası ve primler', 'full-time', 'on-site', 'mid', 'İstanbul, Türkiye', 85000, 135000, 'TRY', true, 'https://kariyer.baykar.com/jobs', 'careers@baykar.com', '2027-01-01', 'open', false, 0);
INSERT INTO job_postings (company_name, title, category, description, requirements, benefits, employment_type, workplace_type, experience_level, location, salary_min, salary_max, currency, is_salary_visible, application_url, contact_email, deadline, status, is_featured, views_count) VALUES ('Microsoft', 'Full Stack Web Developer (Node.js / Vue.js)', 'Yazılım Geliştirme', 'Bulut tabanlı kurumsal yazılım çözümlerimizde uçtan uca modern web teknolojileri ile geliştirmeler yapacak Full Stack Developer arıyoruz.', '• Node.js, Express/Fastify ve modern SQL/NoSQL veritabanları bilgisi\n• Vue.js veya React ile responsive kullanıcı arayüzü tasarımı\n• RESTful API ve GraphQL servis entegrasyonu tecrübesi\n• Git, Docker ve test odaklı geliştirme (TDD) anlayışı', '• Küresel şirket içi kariyer geçiş imkanları\n• Tam donanımlı ev ofis desteği ve ergonomik çalışma koltuğu\n• Yıllık sağlık, fitness ve hobi bütçesi\n• Düzenli şirket hissesi hakedişleri', 'full-time', 'remote', 'mid', 'Remote / Türkiye Geneli', 85000, 130000, 'TRY', true, 'https://kariyer.microsoft.com/jobs', 'careers@microsoft.com', '2027-01-08', 'open', false, 0);